import { test, expect } from '@playwright/test';

test.describe('Out of Stock Item in Cart', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/products');
  });

  test('should display out of stock message when adding unavailable item to cart', async ({ page }) => {
    // Locate and click on the unavailable item
    const unavailableItem = page.getByRole('button', { name: /unavailable item/i });
    await unavailableItem.click();

    // Verify item details are visible
    const itemName = page.getByText('Unavailable Item');
    await expect(itemName).toBeVisible();

    // Verify out of stock label is present
    const outOfStockLabel = page.getByText('Out of Stock');
    await expect(outOfStockLabel).toBeVisible();

    // Attempt to add to cart
    const addToCartButton = page.getByRole('button', { name: /add to cart/i });
    await addToCartButton.click();

    // Verify error message appears
    const errorMessage = page.getByText('This item is currently out of stock');
    await expect(errorMessage).toBeVisible();

    // Verify cart icon does not update
    const cartIcon = page.getByRole('button', { name: /cart/i });
    await expect(cartIcon).toHaveCount(1);
  });

  test('should allow user to remove out of stock item from cart', async ({ page }) => {
    // Add an available item to cart
    const availableItem = page.getByRole('button', { name: /available item/i });
    await availableItem.click();
    const addToCartButton = page.getByRole('button', { name: /add to cart/i });
    await addToCartButton.click();

    // Navigate to cart
    const cartLink = page.getByRole('link', { name: /cart/i });
    await cartLink.click();

    // Add out of stock item to cart
    const unavailableItem = page.getByRole('button', { name: /unavailable item/i });
    await unavailableItem.click();
    const addToCartButtonUnavailable = page.getByRole('button', { name: /add to cart/i });
    await addToCartButtonUnavailable.click();

    // Verify out of stock message is displayed
    const errorMessage = page.getByText('This item is currently out of stock');
    await expect(errorMessage).toBeVisible();

    // Verify out of stock item is in cart with warning
    const cartItem = page.getByText('Unavailable Item');
    await expect(cartItem).toBeVisible();

    const outOfStockWarning = page.getByText('Out of Stock');
    await expect(outOfStockWarning).toBeVisible();

    // Remove the out of stock item
    const removeButton = page.getByRole('button', { name: /remove/i });
    await removeButton.click();

    // Verify out of stock item is removed from cart
    await expect(cartItem).not.toBeVisible();
    await expect(errorMessage).not.toBeVisible();
  });
});
